-- TeknoVersus — 25 Kasım 2026 günlük haberler (3 adet, görselli). Supabase SQL Editor'de çalıştır.
begin;
insert into news (id, title, cat, date, summary, body, related_product_id, tldr, table_data, faq, conclusion) values
('huawei-mate-90-air-tanitildi-7-inc-ekran-6-58-mm-6500-mah', 'Huawei Mate 90 Air Tanıtıldı: 7 İnç Ekran, 6,58 mm Gövde ve 6.500 mAh Pil', 'Telefon', '2026-11-25', 'Huawei, ince telefon serisinin yeni modeli Mate 90 Air''i Çin''de tanıttı. 7 inçlik ekranı 6,58 mm''lik bir gövdeye sığdıran telefon Kirin 9020 işlemci, 6.500 mAh pil ve IP68/IP69 dayanıklılıkla geliyor. Fiyat 4.999 yuan''dan başlıyor, yani Mate 70 Air''den 800 yuan daha pahalı.', '["Huawei, 24 Kasım''daki etkinlikte Mate X8''in yanında Mate 90 Air''i de tanıttı. Telefon, geçen yıl çıkan Mate 70 Air''in devamı. Yine 7 inçlik büyük bir ekranı ince bir gövdede sunmaya odaklanıyor. Kalınlık kamera çıkıntısı hariç 6,58 mm, ağırlık ise 208 gram. iPhone Air ve Galaxy S25 Edge gibi ince telefonlarla aynı fikirden yola çıkıyor, ancak ekranı onlardan belirgin şekilde büyük.", "Ekran 7 inç, 1,5K çözünürlüklü ve 120 Hz yenileme hızına sahip bir OLED panel. Huawei tepe parlaklığı 4.000 nit olarak veriyor. Ekran kalem desteği de sunuyor, ancak kalem kutudan çıkmıyor ve ayrıca satılıyor. İşlemci tarafında Mate 70 Air''deki Kirin 9020A''nın yerini Kirin 9020 almış. Huawei tek çekirdekte yüzde 9''a, çok çekirdekte ise yüzde 36''ya varan artış olduğunu söylüyor. RAM tüm sürümlerde 12 GB.", "İnce telefonlarda en çok merak edilen konu pil. Mate 90 Air''de 6.500 mAh''lik bir pil var (Huawei''nin verdiği nominal değer 6.380 mAh) ve kablolu şarj 66 W. Bu kapasite, 6,5 mm civarındaki rakiplerin çoğunun çok üzerinde. Kamerada 50 MP ana kamera (1/1,3 inç, OIS), 3x optik yakınlaştırmalı 12 MP telefoto ve 8 MP ultra geniş açı kamera bulunuyor. Ön kamera 10,7 MP. Telefon IP68 ve IP69 sertifikalı, yazılım olarak HarmonyOS 7 ile geliyor.", "Çin''de 12 GB + 256 GB sürüm 4.999 yuan, 12 GB + 512 GB sürüm 5.999 yuan. Mate 70 Air 4.199 yuan''dan çıkmıştı, yani başlangıç fiyatı 800 yuan arttı. Renk seçenekleri gül altını, ay gümüşü ve obsidyen siyahı. Huawei telefonun Çin dışında satılıp satılmayacağını açıklamadı. Bu nedenle Türkiye için şimdilik bir tarih ya da fiyat beklentisi yok."]'::jsonb, null, 'Huawei Mate 90 Air Çin''de tanıtıldı: 7 inç 120 Hz OLED ekran, 6,58 mm kalınlık, 208 g, Kirin 9020, 6.500 mAh pil, 66 W şarj, IP68/IP69. Fiyat 4.999 yuan''dan başlıyor. Global satış planı açıklanmadı.', '[{"k": "Ekran", "v": "7 inç OLED, 1,5K, 120 Hz, 4.000 nit, kalem desteği"}, {"k": "Kalınlık / ağırlık", "v": "6,58 mm (kamera hariç) · 208 g"}, {"k": "İşlemci", "v": "Kirin 9020 (Mate 70 Air: Kirin 9020A)"}, {"k": "RAM / depolama", "v": "12 GB · 256 GB / 512 GB"}, {"k": "Ana kamera", "v": "50 MP, 1/1,3 inç, f/1.8, OIS"}, {"k": "Telefoto", "v": "12 MP, 3x optik, OIS"}, {"k": "Ultra geniş / ön", "v": "8 MP / 10,7 MP"}, {"k": "Pil / şarj", "v": "6.500 mAh (nominal 6.380 mAh) · 66 W kablolu"}, {"k": "Dayanıklılık", "v": "IP68 / IP69"}, {"k": "Yazılım", "v": "HarmonyOS 7"}, {"k": "Çin fiyatı", "v": "12/256 GB 4.999 yuan · 12/512 GB 5.999 yuan"}]'::jsonb, '[{"q": "Huawei Mate 90 Air ne kadar ince?", "a": "Kamera çıkıntısı hariç 6,58 mm. Ağırlığı 208 gram."}, {"q": "Mate 90 Air''in pili kaç mAh?", "a": "6.500 mAh (nominal değer 6.380 mAh). Kablolu şarj hızı 66 W."}, {"q": "Mate 90 Air''in fiyatı ne kadar?", "a": "Çin''de 12 GB + 256 GB sürüm 4.999 yuan, 12 GB + 512 GB sürüm 5.999 yuan."}, {"q": "Mate 90 Air Türkiye''ye gelecek mi?", "a": "Huawei Çin dışı satış planı hakkında henüz bir açıklama yapmadı."}]'::jsonb, 'Mate 90 Air büyük değişiklikler getirmiyor. Daha güçlü bir işlemci ve IP69 sertifikası dışında Mate 70 Air''e çok benziyor ve fiyatı arttı. Yine de 7 inç ekranı 6,58 mm gövdeye 6.500 mAh pille sığdırmak, ince telefon kategorisinde pil konusundaki endişeleri gideren nadir örneklerden biri.'),
('vivo-x500-serisi-hindistan-26-kasim-lansman-200-mp-telefoto', 'vivo X500 Serisi Yarın Hindistan''da: 200 MP Telefoto, 8.000 mAh Pil ve Avrupa Fiyatları', 'Telefon', '2026-11-25', 'vivo X500, X500 Pro ve X500 Pro Max 26 Kasım''da Hindistan''da tanıtılıyor. Seri eylülde Çin''de, ekim sonunda da Avrupa''da satışa çıkmıştı. Pro Max''te 200 MP periskop telefoto ve 8.000 mAh pil var; Avrupa fiyatı 1.499 euro''dan başlıyor.', '["vivo''nun yeni amiral gemisi serisi X500, 26 Kasım''da Hindistan''da tanıtılacak. Etkinlik Türkiye saatiyle 09.30''da başlıyor ve vivo''nun YouTube kanalından yayınlanacak. Serinin üç modeli de aslında yeni değil: X500 ailesi eylül sonunda Çin''de satışa çıktı, Pro ve Pro Max ise 27 Ekim''de Avrupa''da tanıtıldı. Hindistan, vivo''nun en büyük pazarlarından biri. X serisinin ilk Pro Max modeli olan X500 Pro Max de bu lansmanla birlikte Hindistan''a gelmiş olacak.", "En dikkat çeken model X500 Pro Max. 6,85 inç, 1440p çözünürlüklü LTPO AMOLED ekran, MediaTek Dimensity 9600 Pro işlemci ve 8.000 mAh silikon-karbon pil kullanılıyor. Kamerada 50 MP Sony LYTIA 910 ana sensörün (1/1,28 inç) yanında 3,5x optik yakınlaştırmalı 200 MP periskop telefoto var. Bu sensör 1/1,4 inç ile pek çok telefonun ana kamerasından büyük. Telefon 8K 30 fps ve 4K 240 fps video çekebiliyor ve 229 gram ağırlığında.", "X500 Pro daha kompakt bir seçenek: 6,36 inç ekran, aynı işlemci, 64 MP 3,5x periskop telefoto ve 6.510 mAh pil, 197 gram ağırlık. Standart X500 ise Dimensity 9600M işlemci, 6,59 inç ekran, 64 MP telefoto ve 7.500 mAh pil sunuyor. Üç modelde de 90 W kablolu ve 40 W kablosuz şarj, IP68/IP69 sertifikası ve Android 17 tabanlı OriginOS 7 var. Pro ve Pro Max, ayrı satılan Zeiss telefoto eklentisini de destekliyor.", "Avrupa''da X500 Pro 1.299 euro (12/256 GB), X500 Pro Max ise 1.499 euro''dan başlıyor. Fotoğraf kitiyle gelen 1 TB''lık Pro Max 2.199 euro. Çin''de fiyatlar X500 için 5.499, Pro için 6.499, Pro Max için 6.999 yuan. Hindistan fiyatları yarın açıklanacak. Sızan kutu fiyatları Pro Max için 2,15 lakh rupi civarını gösteriyor, ancak bunlar etiket fiyatı ve satış fiyatı daha düşük olabilir. vivo Türkiye''de V serisi telefonlarını satıyor, ancak X500''ün buraya gelip gelmeyeceği henüz açıklanmadı."]'::jsonb, null, 'vivo X500 serisi 26 Kasım''da Hindistan''da tanıtılıyor. Pro Max: Dimensity 9600 Pro, 6,85 inç ekran, 200 MP 3,5x periskop, 8.000 mAh pil. Avrupa fiyatları: Pro 1.299 euro, Pro Max 1.499 euro''dan başlıyor. Türkiye planı belli değil.', '[{"k": "Model", "v": "X500 · X500 Pro · X500 Pro Max"}, {"k": "İşlemci", "v": "Dimensity 9600M · 9600 Pro · 9600 Pro"}, {"k": "Ekran", "v": "6,59 inç · 6,36 inç · 6,85 inç (144 Hz)"}, {"k": "Telefoto", "v": "64 MP · 64 MP 3,5x periskop · 200 MP 3,5x periskop"}, {"k": "Ana kamera", "v": "50 MP (tüm modeller)"}, {"k": "Pil", "v": "7.500 · 6.510 · 8.000 mAh"}, {"k": "Şarj", "v": "90 W kablolu, 40 W kablosuz"}, {"k": "Ağırlık", "v": "211 g · 197 g · 229 g"}, {"k": "Dayanıklılık", "v": "IP68 / IP69"}, {"k": "Çin fiyatı", "v": "5.499 · 6.499 · 6.999 yuan"}, {"k": "Avrupa fiyatı", "v": "— · 1.299 euro · 1.499 euro"}]'::jsonb, '[{"q": "vivo X500 Hindistan''da ne zaman tanıtılıyor?", "a": "26 Kasım''da, Türkiye saatiyle 09.30''da başlayan etkinlikte."}, {"q": "X500 Pro Max''in telefoto kamerası kaç MP?", "a": "200 MP. 3,5x optik yakınlaştırma sunan periskop sensör 1/1,4 inç boyutunda."}, {"q": "X500 serisinin Avrupa fiyatı ne kadar?", "a": "X500 Pro 1.299 euro, X500 Pro Max 1.499 euro''dan başlıyor. Standart X500 Avrupa''da satılmıyor."}, {"q": "vivo X500 Türkiye''ye gelecek mi?", "a": "vivo henüz açıklama yapmadı. Türkiye için tarih ya da fiyat bilgisi yok."}]'::jsonb, 'X500 serisinin Hindistan lansmanı yeni bir donanım getirmiyor, ama bölgesel fiyatlar serinin nasıl konumlanacağını gösterecek. Kâğıt üzerinde X500 Pro Max, 200 MP telefoto ve 8.000 mAh pille kamera odaklı amiral gemileri arasında en güçlü seçeneklerden biri. Türkiye için bir açıklama olursa bu haberi güncelleyeceğiz.'),
('galaxy-s27-ultra-lazer-otomatik-odaklama-sensoru-kaldiriliyor-iddiasi', 'Galaxy S27 Ultra''da Lazer Otomatik Odaklama Sensörü de Kaldırılıyor İddiası', 'Telefon', '2026-11-25', 'Sızıntılarıyla bilinen Ice Universe''e göre Samsung, Galaxy S27 Ultra''da 2021''den beri kullandığı lazer otomatik odaklama sensörünü çıkarıyor. Daha önce 3x telefoto kameranın da kaldırılacağı iddia edilmişti. Samsung konuyla ilgili açıklama yapmadı.', '["Galaxy S27 Ultra''nın arka yüzüyle ilgili yeni bir iddia var. Samsung sızıntılarıyla tanınan Ice Universe, 24 Kasım''da X''te yaptığı paylaşımda telefonun lazer otomatik odaklama sensörünü kaybedeceğini yazdı. Bu sensör, Galaxy S21 Ultra''dan beri her Ultra modelde kamera adalarının yanında küçük bir delik olarak yer alıyor. Samsung''dan doğrulama yok, bu yüzden bilgiyi şimdilik iddia olarak değerlendirmek gerekiyor.", "Lazer sensörü, telefonun konuya olan mesafesini ölçerek özellikle karanlık ortamlarda ve yakın çekimlerde odaklamayı hızlandırıyor. GSMArena''nın haberine göre Samsung bu görevi yapay zeka destekli odaklama ile üstlenmeyi planlıyor olabilir. Bugün birçok telefon, sensörün kendi faz algılamalı odaklama sistemiyle lazer olmadan da iyi sonuç veriyor. Asıl soru, düşük ışıkta ve yakın çekimde farkın hissedilip hissedilmeyeceği.", "Bu, S27 Ultra''nın kamerasıyla ilgili ilk değişiklik iddiası değil. Ice Universe''ün 15 Kasım''da paylaştığı çizimde telefonun arkasında yalnızca üç kamera görünüyordu. Beklenen düzen 200 MP ana kamera, 50 MP ultra geniş açı ve 5x optik yakınlaştırmalı 50 MP telefoto. S26 Ultra''daki 10 MP''lik 3x telefoto kaldırılırsa, 3x civarındaki çekimler 200 MP ana sensörden kırpılarak yapılacak. Bu sensörün yeni ve daha büyük bir model olması bekleniyor.", "Samsung''un Galaxy S27 serisini Ocak 2027''de, en geç şubatta tanıtması bekleniyor, ancak tarih henüz resmi değil. Kataloğumuzda yer alan Galaxy S26 Ultra''da hem 3x telefoto hem de lazer odaklama sensörü bulunuyor. İddialar doğru çıkarsa S27 Ultra kâğıt üzerinde daha sade bir kamera düzenine sahip olacak. Bu değişikliğin fotoğraf kalitesine etkisini ancak test edildiğinde göreceğiz."]'::jsonb, 's2', 'Ice Universe''e göre Galaxy S27 Ultra''da lazer otomatik odaklama sensörü olmayacak. 3x telefotonun da kaldırılacağı ve arkada üç kamera (200 MP ana, 50 MP ultra geniş, 50 MP 5x) olacağı iddia ediliyor. Samsung doğrulamadı. Lansman Ocak 2027''de bekleniyor.', '[{"k": "Kaldırılacağı iddia edilen", "v": "Lazer otomatik odaklama sensörü, 3x telefoto"}, {"k": "İddianın kaynağı", "v": "Ice Universe (X, 24 Kasım 2026)"}, {"k": "Beklenen arka kameralar", "v": "200 MP ana · 50 MP ultra geniş · 50 MP 5x telefoto"}, {"k": "S26 Ultra''da", "v": "4 kamera + lazer AF (3x 10 MP telefoto dahil)"}, {"k": "Olası alternatif", "v": "Yapay zeka destekli odaklama (GSMArena)"}, {"k": "Beklenen lansman", "v": "Ocak 2027 (resmi değil)"}]'::jsonb, '[{"q": "Galaxy S27 Ultra''da lazer odaklama olacak mı?", "a": "Ice Universe''e göre olmayacak. Samsung bu konuda açıklama yapmadı, bilgi şimdilik iddia düzeyinde."}, {"q": "Lazer otomatik odaklama ne işe yarıyor?", "a": "Konuya olan mesafeyi ölçerek özellikle karanlık ortamlarda ve yakın çekimlerde odaklamayı hızlandırıyor."}, {"q": "Galaxy S27 Ultra''da kaç kamera olacak?", "a": "Sızıntılara göre arkada üç kamera bekleniyor: 200 MP ana, 50 MP ultra geniş açı ve 50 MP 5x telefoto."}, {"q": "Galaxy S27 Ultra ne zaman çıkacak?", "a": "Ocak 2027''de, en geç şubatta tanıtılması bekleniyor. Samsung tarih açıklamadı."}]'::jsonb, 'Lazer sensörünün ve 3x telefotonun çıkarılması kâğıt üzerinde geri adım gibi görünse de, daha büyük bir ana sensör ve gelişmiş yazılım bu boşluğu doldurabilir. Ice Universe Samsung konusunda genellikle isabetli, ancak kesin sonuç için lansmanı ve ilk testleri beklemek gerekiyor.')
on conflict (id) do nothing;
update news set image_url = 'https://consumer.huawei.com/content/dam/huawei-cbg-site/cn/mkt/pdp/phones/mate90-air/images/design/huawei-mate90-air-colour-01.jpg', image_credit = 'Huawei' where id = 'huawei-mate-90-air-tanitildi-7-inc-ekran-6-58-mm-6500-mah';
update news set image_url = 'https://asia-exstatic-vivofs.vivo.com/PSee2l50xoirPK7y/Picture_library/1793783321080/zip/img/pc2.jpg', image_credit = 'vivo' where id = 'vivo-x500-serisi-hindistan-26-kasim-lansman-200-mp-telefoto';
update news set image_url = 'https://images.samsung.com/uk/smartphones/galaxy-s26-ultra/images/galaxy-s26-ultra-features-kv.jpg', image_credit = 'Samsung' where id = 'galaxy-s27-ultra-lazer-otomatik-odaklama-sensoru-kaldiriliyor-iddiasi';
commit;
select id, image_credit, jsonb_array_length(body) n from news where date = '2026-11-25' order by id;
